const staleDeploymentGrantIDs = `-- name: StaleDeploymentGrantIDs :many
SELECT g.id FROM client_cert_grants g
JOIN certificates ce ON ce.id = g.cert_id
JOIN deployments d ON d.grant_id = g.id
WHERE g.removed_at IS NULL AND ce.current_version_id IS NOT NULL
  AND d.version_id IS DISTINCT FROM ce.current_version_id
`

func (q *Queries) StaleDeploymentGrantIDs(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, staleDeploymentGrantIDs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateGrant = `-- name: UpdateGrant :one
UPDATE client_cert_grants SET delivery = $1, output_spec_id = $2,
       deploy_target_id = $3, hook_ids = $4,
       auto_remediate = $5, updated_at = now()
WHERE id = $6 RETURNING id, client_id, cert_id, delivery, output_spec_id, deploy_target_id, hook_ids, auto_remediate, removed_at, created_at, updated_at, removed_revision
`

type UpdateGrantParams struct {
	Delivery       string      `json:"delivery"`
	OutputSpecID   *uuid.UUID  `json:"output_spec_id"`
	DeployTargetID *uuid.UUID  `json:"deploy_target_id"`
	HookIds        []uuid.UUID `json:"hook_ids"`
	AutoRemediate  bool        `json:"auto_remediate"`
	ID             uuid.UUID   `json:"id"`
}

func (q *Queries) UpdateGrant(ctx context.Context, arg UpdateGrantParams) (ClientCertGrant, error) {
	row := q.db.QueryRow(ctx, updateGrant,
		arg.Delivery,
		arg.OutputSpecID,
		arg.DeployTargetID,
		arg.HookIds,
		arg.AutoRemediate,
		arg.ID,
	)
	var i ClientCertGrant
	err := row.Scan(
		&i.ID,
		&i.ClientID,
		&i.CertID,
		&i.Delivery,
		&i.OutputSpecID,
		&i.DeployTargetID,
		&i.HookIds,
		&i.AutoRemediate,
		&i.RemovedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RemovedRevision,
	)
	return i, err
}

const upsertDeployment = `-- name: UpsertDeployment :exec
INSERT INTO deployments (grant_id, version_id, state, expected, error, updated_at)
VALUES ($1, $2, 'pending', $3, '', now())
ON CONFLICT (grant_id) DO UPDATE SET version_id = EXCLUDED.version_id, state = 'pending',
       expected = EXCLUDED.expected, error = '', updated_at = now()
`

type UpsertDeploymentParams struct {
	GrantID   uuid.UUID  `json:"grant_id"`
	VersionID *uuid.UUID `json:"version_id"`
	Expected  []byte     `json:"expected"`
}

func (q *Queries) UpsertDeployment(ctx context.Context, arg UpsertDeploymentParams) error {
	_, err := q.db.Exec(ctx, upsertDeployment, arg.GrantID, arg.VersionID, arg.Expected)
	return err
}
